//! Ambition's authored audio registries — CONTENT data, evicted from the
//! engine core (R3.2: the engine ships no tracks and no cues).
//!
//! - `music_registry.ron` is GENERATED by `scripts/regen_music_registry.py`
//!   from the rendered-OGG asset tree; do not hand-edit.
//! - `sfx_registry.ron` is hand-authored synth-cue data.
//!
//! Providers register both through `ambition_audio::catalog`; hosts select a
//! provider or deterministic combination and insert the playback resources they
//! need. Audio authority is fully App-local — no process-global install seam.


use ambition_platformer2d::content::MusicRegistry;
use ambition_platformer2d::content::SfxRegistry;
// The music and SFX registries are pack sources (`audio/*.ron` in `pack.ron`):
// read off disk in a development build, so a music regen or a cue edit is no
// Rust build, and embedded by `build.rs` under `static_content`.

/// Register Ambition's immutable audio fragments in one Bevy `App`, lowered
/// from the App's selected pack. This is the sole authority: hosts read the
/// assembled registries from the `AudioCatalogRegistry` resource (no
/// process-global install seam remains).
///
/// A registry that the pack does not have is not registered. The music
/// registry is generated content: before the music is rendered, the pack
/// compiles without it (with a loud warning), and this App plays no music.
pub fn register(app: &mut bevy::prelude::App) {
    use ambition_audio::catalog::{AudioCatalogAppExt, AudioCatalogFragment};

    let pack = crate::pack::select(app.world_mut());
    app.register_audio_catalog_fragment(
        AudioCatalogFragment::new(
            crate::AMBITION_CONTENT_PROVIDER,
            music_registry_of(&pack),
            sfx_registry_of(&pack),
        )
        .expect("Ambition audio catalogs should be valid"),
    );
}

/// The music registry of `pack` (generated by `scripts/regen_music_registry.py`).
/// `None` when the music is not generated yet: the pack then has no
/// `music_registry` content, and the game plays no music.
///
/// `MusicRegistry::validate()` did run, but only later and only inside `AudioCatalogFragment::new`,
/// which needs an App; and nothing anywhere asked whether the OGG each track points at exists. The
/// `music_registry` schema declares every track's audio file as a requirement, so a strict asset
/// check reports a track whose file was never rendered.
pub fn music_registry_of(pack: &ambition_content_pack::PreparedContentPack) -> Option<MusicRegistry> {
    ambition_audio::content_schema::lowered_music_registry(pack).cloned()
}

/// The music registry of Ambition's SHIPPED pack: for a validator or a test
/// whose subject is the shipped product, not a composition. `None` when the
/// music is not generated yet.
pub fn shipped_music_registry() -> Option<MusicRegistry> {
    music_registry_of(crate::pack::shipped())
}

/// The hand-authored SFX synthesis registry. Same move as the music registry:
/// the compiler's lowered artifact, not a re-parse. `None` when the pack
/// declares no SFX registry.
pub fn sfx_registry_of(pack: &ambition_content_pack::PreparedContentPack) -> Option<SfxRegistry> {
    ambition_audio::content_schema::lowered_sfx_registry(pack).cloned()
}

#[cfg(test)]
mod tests {
    /// The SFX registry is authored, so it is always there. The music
    /// registry is generated, so this test needs the rendered music
    /// (`scripts/regen/music.sh`).
    #[test]
    fn both_registries_parse() {
        let music = super::shipped_music_registry()
            .expect("the music registry is generated content: run scripts/regen/music.sh");
        assert!(
            !music.tracks.is_empty(),
            "music registry should have tracks"
        );
        super::sfx_registry_of(crate::pack::shipped()).expect("the SFX registry is authored");
    }
}
